mapper.update:
UPDATE schedule_reservation SET status='CONFIRMED',version=version+1,updated_at=#{now}
WHERE id=#{reservationId} AND order_id=#{orderId} AND store_id=#{storeId}
  AND status='TEMP_LOCKED' AND version=#{version} AND lock_expire_at=#{expires}

UPDATE schedule_reservation SET status='EXPIRED',version=version+1,updated_at=#{now}
WHERE id=#{reservationId} AND status='TEMP_LOCKED' AND version=#{version}
  AND lock_expire_at=#{expires}

UPDATE schedule_availability_window
SET status=#{nextStatus},version=version+1,updated_at=#{now}
WHERE id=#{windowId} AND status=#{expectedStatus}

